"""Top shipments by weight."""


def _take_largest(shipments):
    """Remove and return the shipment with the largest weight."""
    best = max(shipments, key=lambda x: x.weight)
    shipments.remove(best)
    return best


def podium(shipments, places=3):
    """Return the top `places` shipments by weight, largest first. The caller's list is left as it was."""
    top = []
    while shipments and len(top) < places:
        top.append(_take_largest(shipments))
    return top


def report(shipments):
    """Return the podium values, the number of shipments and every weight."""
    return {"podium": [x.weight for x in podium(shipments)], "count": len(shipments), "all": [x.weight for x in shipments]}


def group_by_route(shipments):
    """Return a dict from route to the list of shipments with that route."""
    groups = {}
    for x in shipments:
        groups.setdefault(x.route, []).append(x)
    return groups

