from shipments import load_shipments, ROWS
from podium import podium, report

VALUES = [v for _, v in ROWS]


def test_count():
    assert report(list(load_shipments()))["count"] == len(ROWS)


def test_all_values_kept():
    assert report(list(load_shipments()))["all"] == VALUES


def test_podium_values():
    top = podium(list(load_shipments()))
    assert [x.weight for x in top] == sorted(VALUES, reverse=True)[:3]


def test_caller_list_unchanged():
    data = list(load_shipments())
    podium(data, 2)
    assert [x.weight for x in data] == VALUES


def test_one_place():
    assert [x.weight for x in podium(list(load_shipments()), 1)] == [max(VALUES)]
